'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',
 arrow:'M12 19V5M6 11l6-6 6 6',plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',
 calendar:'M5 5h14v15H5zM8 3v4M16 3v4M5 10h14',context:'M4 4h16v13H4zM8 21h8M12 17v4',
 history:'M4 9a8 8 0 1 1 0 7M4 4v5h5M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',
 shield:'M12 3l8 3v6c0 5-8 9-8 9S4 17 4 12V6zM8 12l3 3 5-6',check:'M5 12l4 4L19 6',
 chevron:'M9 5l7 7-7 7',back:'M15 5l-7 7 7 7',text:'M4 5h16M4 10h12M4 15h16M4 20h9',
 link:'M9 8l2-2a5 5 0 0 1 7 7l-2 2M8 9l-2 2a5 5 0 0 0 7 7l2-2M8 16l8-8',
 copy:'M8 8h12v13H8zM16 8V3H3v13h5',share:'M12 14V2M7 7l5-5 5 5M6 10H3v11h18V10h-3',
 speaker:'M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5zM10 20h4',
 person:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 21v-3a8 8 0 0 1 16 0v3',file:'M5 3h9l5 5v13H5zM14 3v5h5',
 photo:'M3 4h18v16H3zM3 16l6-6 6 7 3-3 3 4M16 8h.01',camera:'M3 7h5l2-3h4l2 3h5v14H3zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',
 stop:'M6 6h12v12H6z',mail:'M3 5h18v14H3zM3 5l9 8 9-8',device:'M7 2h10v20H7zM10 18h4',
 search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',warning:'M12 3l10 18H2zM12 9v5M12 17h.01'
};
const icon = name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.text}"/></svg>`;
const face = `<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M14 43L29 28L44 43M56 43L71 28L86 43M34 62L50 77L66 62"/></svg>`;
const presence=(state='idle',size='')=>`<div class="presence ${state==='idle'?'':'active'} ${size}" role="img" aria-label="Suzzme: ${escapeHTML(state)}">${face}</div>`;
const button=(label,action,kind='',extra='')=>`<button class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const go=(label,route,kind='',extra='')=>button(label,`go:${route}`,kind,extra);
const row=(symbol,title,detail,tail,action)=>`<${action?'button':'div'} class="row" ${action?`data-action="${action}"`:''}>${icon(symbol)}<span class="row-content"><span class="row-title">${title}</span><span class="row-detail">${detail}</span></span><span class="row-tail">${tail||''}</span></${action?'button':'div'}>`;
const toggle=(label,key)=>`<label class="toggle"><span>${label}</span><input type="checkbox" data-toggle="${key}" ${state.toggles[key]?'checked':''}></label>`;
const chip=label=>`<span class="chip">${label}</span>`;
const topbar=(title,back='home')=>`<div class="topbar">${go(icon('back')+'Back',back)}<h3>${title}</h3>${go(icon('settings'),'settings','','aria-label="Settings"')}</div>`;
const page=(content,classes='')=>`<div class="page ${classes}">${content}</div>`;
const heading=(title,copy='')=>`<h3 class="heading">${title}</h3>${copy?`<p class="secondary">${copy}</p>`:''}`;
const composer=()=>`<div class="bottom"><div class="composer">${go(icon('plus'),'attachment','','aria-label="Add context"')}<input id="question" aria-label="Ask Suzzme" placeholder="Ask anything…" autocomplete="off">${button(icon('mic'),'voice-start','','aria-label="Talk to Suzzme"')}${button(icon('arrow'),'ask','send','aria-label="Send question"')}</div><p class="micro" style="margin:10px 4px 0">${state.shared?'Using your selected text · This session only':'Nothing is being shared with Suzzme.'}</p></div>`;
const sections=[
 ['Foundations','foundations'],['Colors','colors'],['Typography','typography'],['Components','components'],['Presence System','presence'],['iPhone Onboarding','welcome'],['iPhone Home','home'],['Conversation','conversation'],['Voice','voice'],['Dynamic Island','island'],['Context','context'],['History','history'],['Integrations','services'],['Settings','settings'],['macOS Menu Bar','menu'],['macOS Notch','notch'],['macOS Floating Assistant','floating'],['macOS Main Window','mac-window'],['Permissions & Privacy','permissions'],['Errors / Empty States','errors'],['Light Mode','light'],['Dark Mode','dark'],['Prototype Flows','flows']
];
const state={route:'home',appearance:'light',viewport:'phone',motion:false,largeText:false,voice:'Listening',shared:false,permission:null,permissionStatus:{},connected:false,question:'Help me prepare for my design review.',history:[],historyQuery:'',deleted:null,confirmed:false,flow:null,step:0,toggles:{proactive:false,preview:false,live:true,remember:false,sync:false,contrast:false,transparency:false},error:'offline'};
const specs={
 foundations:['01 — Foundations','The companion comes first','Presence is the signature; native controls carry everything else.','SwiftUI owns layout. Keep existing engines, routes and SuzzmeFace geometry.'],
 colors:['02 — Colors','A neutral canvas. A violet signal.','Semantic color pairs reserve violet for active intelligence.','Map values to SuzzmeTheme and asset-catalog appearances; use Color.primary/secondary in native screens.'],
 typography:['03 — Typography','A comfortable reading rhythm','System text styles scale with accessibility settings.','Use .font(.body), .title, .headline and .caption. Never cap Dynamic Type in production.'],
 components:['04 — Components','Built once. Used everywhere.','Reusable controls share spacing, focus and state semantics.','Prototype SVG symbols are editable stand-ins; production uses SF Symbols.'],
 presence:['05 — Presence System','One face. Every state.','The established three-stroke face remains recognizable in all states.','Bind SuzzmeAssistantPresenceView to AssistantStateController; do not add a second state machine.'],
 welcome:['06 — iPhone Onboarding','Meet Suzzme','A short, optional introduction leads directly to useful assistance.','No permission prompt on launch. Permission requests follow the chosen feature.'],
 home:['07 — iPhone Home','There when you need it','A quiet entrance with one primary voice action and useful suggestions.','Use HomeView, SuzzmeGreeting and existing typed/voice pipelines.'],
 conversation:['08 — Conversation','Space for a useful answer','Readable answers, compact user messages and visible source provenance.','Use AskSuzzmeView. Sample answers here are authored fixtures, not model output.'],
 voice:['09 — Voice','A conversation without clutter','State text and simple controls accompany gentle presence motion.','VoiceSessionController owns microphone, transcription, cancellation and speech.'],
 island:['10 — Dynamic Island','Continuity at a glance','Compact and expanded content regions for an eligible, active session.','Layout study only: ActivityKit/WidgetKit owns presentation and duration. No persistent idle island.'],
 context:['11 — Context','Only what you choose to share','Show scope, source, processing route and a visible Stop Sharing action.','Screen context is macOS-only and explicit. iPhone uses selected text, files or system sharing.'],
 history:['12 — History','Pick up where you left off','Search and date groups support recent work without becoming the home screen.','Bind HistoryView to local persistence. Demo history is memory-only and resets on reload.'],
 services:['13 — Integrations','Connect what matters','Device sources and network accounts have separate groups and clear access scopes.','Bind to real source health and GmailAccountController. No simulated OAuth in production.'],
 settings:['14 — Settings','Make Suzzme yours','Native groups keep voice, intelligence, privacy and devices easy to find.','Use existing Settings scenes; avoid duplicate Memory or Sources destinations.'],
 menu:['15 — macOS Menu Bar','A useful little window','Quick input, voice and the last interaction live in a compact popover.','MenuBarExtra presents app-owned content; menu bar icon has a monochrome Face.'],
 notch:['16 — macOS Notch','An anchor above your work','A compact app-owned panel sits below the hardware, never recolors it.','MacAssistantPresence detects geometry; non-notch Macs fall back to the menu bar or floating panel.'],
 floating:['17 — macOS Floating Assistant','A thought away','A short answer can naturally open into the full conversation window.','Public NSPanel/window APIs; configurable global shortcut, Escape dismisses.'],
 'mac-window':['18 — macOS Main Window','Room to think','A task-focused window with an optional context area and discoverable navigation.','Proposed compact toolbar navigation. Preserve existing routes; migrate native sidebar only after implementation validation.'],
 permissions:['19 — Permissions & Privacy','You decide what Suzzme can use','Every row explains purpose, current status and a next action.','Status comes from system APIs. Simulated responses do not call system settings or permission APIs.'],
 errors:['20 — Errors / Empty States','A way forward','Explain what happened and offer one useful recovery action.','Translate engine errors to human copy, preserve drafts and distinguish healthy-empty from unavailable.'],
 light:['21 — Light Mode','Light, quietly','Neutral surfaces and generous spacing keep the presence intentional.','Uses existing light tokens; appearance choice also updates all prototype screens.'],
 dark:['22 — Dark Mode','A softer kind of dark','Near-black canvas and separated elevations keep text readable.','Uses existing dark tokens; appearance choice also updates all prototype screens.'],
 flows:['23 — Prototype Flows','From intent to outcome','Eight guided journeys include cancellation and permission boundaries.','Next/Back are design-review controls outside the product. Production state comes from existing controllers.']
};
function specFor(route){if(specs[route])return specs[route];if(['splash','devices-intro','privacy-intro','voice-intro','context-intro','connect-intro','ready'].includes(route))return specs.welcome;if(['action','success','thinking'].includes(route))return specs.conversation;if(['permission-explainer','system-permission','privacy','memory'].includes(route))return specs.permissions;if(['appearance','voice-settings','intelligence-settings','notifications','devices','about','general'].includes(route))return specs.settings;if(['service-detail'].includes(route))return specs.services;return specs.context;}
function renderCatalog(query=''){const nav=$('#catalog');nav.innerHTML=sections.map(([title,route],i)=>({title,route,i})).filter(x=>x.title.toLowerCase().includes(query.toLowerCase())).map(x=>`<button data-action="go:${x.route}" ${specFor(state.route)[0].startsWith(String(x.i+1).padStart(2,'0'))?'aria-current="page"':''}><span>${String(x.i+1).padStart(2,'0')}</span>${x.title}</button>`).join('');}
function render(){const spec=specFor(state.route);$('#screen-section').textContent=spec[0];$('#screen-title').textContent=spec[1];$('#intent').textContent=spec[2];$('#implementation').textContent=spec[3];$('#viewport').value=state.viewport;$('#appearance').value=state.appearance;const dark=state.appearance==='dark'||(state.appearance==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);const dev=$('#device');dev.className=[state.viewport,dark?'dark':'',state.motion?'no-motion':'',state.largeText?'large-type':'',state.toggles.contrast?'high-contrast':'',state.toggles.transparency?'opaque':''].join(' ');const mac=state.viewport.startsWith('mac');$('#chrome').innerHTML=mac?'<div class="mac-chrome"><span class="dot"></span><span class="dot"></span><span class="dot"></span><span>Suzzme</span></div>':'<div class="phone-chrome"><span>9:41</span><span aria-label="Device status illustration">••• ━ ▰</span></div>';$('#screen').innerHTML=screenContent(state.route);renderCatalog($('#catalog-search').value);renderFlow();}
function navigate(route){state.route=route;location.hash=route;render();}
function sampleResponse(){return `<div class="response"><div class="byline">${presence('idle','tiny')}<span>Suzzme</span></div><h4>Start with the decision you need.</h4><p>Keep your review focused on three things:</p><ol><li>The problem this design solves.</li><li>The tradeoff you want feedback on.</li><li>The next decision and who owns it.</li></ol><p>Close by agreeing on one next step. You can keep the supporting details nearby without leading with them.</p><div class="chips">${chip(state.shared?'Selected text · This session':'General guidance · No personal sources')}</div><div class="response-actions">${button(icon('copy')+'Copy','copy')}${button(icon('speaker')+'Read Aloud','read')}${go(icon('share')+'Share','share')}</div></div>`;}
function home(){return `<div class="topbar"><span class="micro">Suzzme</span><div class="buttons">${go(icon('history'),'history','','aria-label="History"')}${go(icon('settings'),'settings','','aria-label="Settings"')}</div></div>`+page(`<p class="secondary">A little space to think.</p><h3 class="heading">What’s on your mind?</h3>${presence('idle')}<p class="status">Ready when you are.</p><div style="height:28px"></div>${button(icon('mic')+' Talk to Suzzme','voice-start','primary wide')}<div style="height:28px"></div><div class="stack">${go(icon('calendar')+' What’s on my schedule?','schedule','suggestion')}${go(icon('context')+' Help me understand this','context','suggestion')}${go(icon('text')+' Summarize something','attachment','suggestion')}</div>`)+composer();}
function onboarding(route){const data={welcome:['Meet Suzzme','Your private personal companion, designed to help across your Apple devices.','Get Started','devices-intro'], 'devices-intro':['Built for your devices','Ask on iPhone. Find a quiet companion in your Mac menu bar. Available features depend on your device.','Continue','privacy-intro'],'privacy-intro':['Private by design','Supported intelligence can run on your device. Connected services use a network and require your authorization.','Continue','voice-intro'],'voice-intro':['Talk naturally','Speak when you want. Type when you prefer. Microphone and speech access are requested only when you start talking.','Continue','context-intro'],'context-intro':['Understand your context','Share selected text or a file. On Mac, choose when to share the current screen. Nothing is watched silently.','Continue','connect-intro'],'connect-intro':['Connect what matters','Calendar, contacts and supported accounts are optional. You can connect them later in Settings.','Continue Without Connecting','ready'],ready:['You’re ready','Suzzme is here when you need a little help.','Open Suzzme','home']}[route];return page(`${presence(route==='ready'?'success':'idle')}<h3 class="brand-heading">${data[0]}</h3><p class="secondary">${data[1]}</p>`,'center')+`<div class="bottom stack">${go(data[2],data[3],'primary wide')}${route==='welcome'?go('Learn About Privacy','privacy','text-button wide'):go('Set Up Later','home','text-button wide')}${route==='connect-intro'?go('Choose Sources','services','text-button wide'):''}<p class="micro" style="text-align:center">No account required to explore.</p></div>`;}
const permissions=[['Microphone','mic','Lets you speak naturally with Suzzme.','Available on iPhone and Mac'],['Speech Recognition','text','Turns your speech into text. Processing availability varies.','Available on supported devices'],['Notifications','bell','Sends the reminders and updates you enable.','Optional'],['Calendar','calendar','Uses your schedule when you ask.','Read access; writes need confirmation'],['Contacts','person','Finds people you ask about.','Optional'],['Photos','photo','Uses only the photos you select.','System photo picker; no library access by default'],['Camera','camera','Captures an image when you choose.','Capability-gated; proposed'],['Files','file','Uses a file you explicitly choose.','System document picker'],['Screen Sharing','context','Uses a snapshot of the Mac screen you choose.','Mac only; explicit invocation']];
function screenContent(route){
 if(['welcome','devices-intro','privacy-intro','voice-intro','context-intro','connect-intro','ready'].includes(route))return onboarding(route);
 switch(route){
 case 'splash':return page(presence('idle'),'center');
 case 'home':case 'mac-window':case 'light':case 'dark':return home();
 case 'foundations':return topbar('Foundations')+page(heading('Present when needed.','Invisible when not.')+presence('idle')+`<p class="secondary">A face you recognize. A quiet signal when intelligence is active. Everything else belongs to the platform.</p><div class="list">${row('device','Adaptive by capability','One identity across iPhone and Mac.','')}${row('shield','Privacy in context','Source, purpose, processing and Stop Sharing.','')}${row('text','Content first','Native forms and readable answers.','')}</div><h4 class="section-heading">Established logo treatments</h4><div class="state-grid"><div class="state-card">${presence('idle','small-presence')}Light surface</div><div class="state-card" style="background:#121212;color:#dab1da">${presence('idle','small-presence')}Dark surface</div></div><p class="small-note">App icon: use the existing asset catalog. Menu bar: monochrome face. Splash and welcome: one mark only.</p>`);
 case 'colors':{const d=$('#device').classList.contains('dark');const pairs=[['Canvas',d?'#121212':'#FFFFFF'],['Surface',d?'#212121':'#F6F6F6'],['Primary text',d?'#F3F3F5':'#202024'],['Secondary text',d?'#AAAAB5':'#63636B'],['Intelligence',d?'#DAB1DA':'#744575'],['Intelligence wash',d?'#302535':'#F5EDF6']];return topbar('Colors')+page(heading('A quiet palette','Purple is a signal, not a background for every screen.')+`<div class="swatches">${pairs.map(([n,c])=>`<div class="swatch"><i style="background:${c}"></i>${n}<p class="micro">${c}</p></div>`).join('')}</div><p class="source-note">Neutral buttons carry ordinary actions. Violet carries voice and active intelligence. Warning and error states always include text.</p>`);}
 case 'typography':return topbar('Typography')+page(heading('System by design','San Francisco, semantic roles, natural scaling.')+`<div class="list">${[['Large Title',34],['Title',28],['Section Title',20],['Body',17],['Secondary Body',15],['Caption',12],['Micro Status',11]].map(([n,s])=>`<div class="row"><span style="font-size:calc(${s}px * var(--type))">${n}</span><span class="row-tail" style="margin-left:auto">${s} pt · iPhone</span></div>`).join('')}</div><p class="small-note">Mac: 28 / 22 / 17 / 13 / 12 / 11 / 10 pt. Use native styles rather than fixed pixel fonts in SwiftUI.</p>`);
 case 'components':return topbar('Components')+page(heading('A shared language','Every control has a purpose, state and accessible name.')+`<div class="component-grid"><div class="buttons">${go('Primary','home','primary')}${go('Secondary','home','secondary-button')}${go(icon('mic'),'voice','','aria-label="Voice icon button"')}</div><div class="chips">${chip('Calendar · On device')}${chip('Gmail · Network')}${chip('This session')}</div><div class="list">${row('shield','Permission row','Benefit before the system request.','Ask','go:permissions')}${row('speaker','Setting row','Native grouped forms.','Manage','go:voice-settings')}</div>${toggle('Proactive assistance','proactive')}<div class="summary"><p class="micro">Confirmation panel</p><h4>Design Review</h4><p>Tomorrow · 3:00 PM · 30 minutes</p>${go('Review Action','action','secondary-button')}</div>${go('Device Card','devices','secondary-button wide')}${go('View Empty, Error & Loading States','errors','text-button wide')}</div>`)+composer();
 case 'presence':return topbar('Presence')+page(heading('One presence, many meanings','Motion follows state. The face stays recognizable.')+`<div class="state-grid">${['Idle','Listening','Understanding','Thinking','Speaking','Working','Success','Error'].map(s=>`<div class="state-card">${presence(s==='Idle'?'idle':s)}<p>${s}</p></div>`).join('')}</div><p class="source-note">Idle is still. Active motion is a subtle stand-in for state transitions. Reduce Motion keeps all statuses visible.</p>`);
 case 'conversation':return topbar('Ask Suzzme')+page(`<div class="transcript"><div class="user-message">${escapeHTML(state.question)}</div>${sampleResponse()}</div><div class="stack" style="margin-top:24px">${button('Make It Shorter','shorten','secondary-button')}${go('Create a Design Review Event','action','text-button')}</div>`,'compact')+composer();
 case 'thinking':return topbar('Ask Suzzme')+page(`${presence('Thinking')}<h3 class="heading">Thinking it through…</h3><p class="secondary">Preparing a response.</p>${button('Cancel','cancel-work','secondary-button')}`,'center')+composer();
 case 'voice':return topbar('Voice')+page(`${presence(state.voice)}<h3 class="heading" role="status">${escapeHTML(state.voice)}…</h3><p class="secondary">${state.voice==='Listening'?'Say what’s on your mind.':state.voice==='Speaking'?'You can interrupt at any time.':'Taking a moment to respond.'}</p><p class="micro">${state.voice==='Listening'?'Demo microphone state · No recording':'Design state preview'}</p>`,'center')+`<div class="bottom stack"><div class="buttons">${button(icon('stop')+' Stop','voice-stop','secondary-button')}${button('End Listening','voice-end','secondary-button')}</div>${go('Return to Text','conversation','text-button wide')}${go('Cancel','home','text-button wide')}${button('Preview Next Voice State','voice-next','text-button wide')}</div>`;
 case 'island':return topbar('Live Activity')+page(heading('A glance, then back to life','System-managed continuity for an eligible active session.')+`<h4 class="section-heading">Compact content regions</h4><div class="island-board"><div class="island-compact">${presence('Listening','tiny')}<span class="hardware-label">Hardware region<br>System reserved</span>${icon('mic')}</div><p class="micro" style="color:#babac4">Content regions only · Not an in-app island overlay</p></div><h4 class="section-heading">Expanded content</h4><div class="island-board"><div class="panel-heading">${presence('Listening','tiny')}<h4>Suzzme</h4><span style="margin-left:auto;font-size:.75em">Listening…</span></div><p class="secondary">Return to Suzzme to continue.</p>${go('Open Suzzme','voice','secondary-button wide')}</div><p class="source-note">No idle activity. No transcript or personal titles on the Lock Screen by default. System controls presentation. A Live Activity does not grant microphone or background execution access.</p>${go('See the Non-Island Alternative','non-island','text-button wide')}`);
 case 'non-island':return topbar('Continuity')+page(heading('The same companion','A complete experience on devices without Dynamic Island.')+presence('Thinking')+`<p class="status">Preparing a response…</p><div class="summary"><h4>Suzzme is working</h4><p class="secondary">Eligible sessions can use a system-managed Lock Screen Live Activity. Otherwise, state remains in the app.</p>${go('Return to Suzzme','conversation','secondary-button')}</div><p class="source-note">No arbitrary overlay above other iPhone apps. Notifications require permission. Session end removes active continuity surfaces.</p>`);
 case 'context':return topbar('Context')+page(heading(state.shared?'Using your selected text':'Choose what to share',state.shared?'Only this session. You can stop at any time.':'Nothing is being shared with Suzzme.')+`<div class="list">${row('text','Selected text','Paste or share a passage you want help with.','Choose','go:attachment')}${row('file','Selected file','Choose one file through the system picker.','Choose','go:attachment')}${row('context','Current screen','Mac only · One chosen snapshot.','Mac','screen-preview')}</div>${state.shared?`<div class="chips">${chip('Selected text')}${chip('This session')}${chip('No network account')}</div><div class="buttons">${button('Stop Sharing','stop-context','secondary-button')}${button('Ask About This','context-ask','primary')}</div>`:go('Try Selected Text','attachment','secondary-button wide')}<p class="source-note">Permission to capture a screen is separate from your choice to share a snapshot. Stop Sharing removes it from active context. History controls govern saved excerpts separately.</p>`);
 case 'attachment':return topbar('Add Context','context')+page(heading('Use only what you choose','This design sample uses an authored passage. No file picker or device access is opened.')+`<div class="summary"><p class="micro">Selected text · Sample</p><p>“We’ll use the design review to choose the next direction, discuss the key tradeoff, and agree on an owner for the follow-up.”</p></div><p class="secondary">Share for this session. No connected service is used in this preview.</p><div class="stack">${button('Use This Sample Text','use-context','primary wide')}${go('Cancel','context','secondary-button wide')}</div>`);
 case 'schedule':state.permission='Calendar';return topbar('Your Schedule')+page(heading('Your calendar is yours','Allow calendar access to answer questions about your schedule.')+`<p class="secondary">You can keep using Suzzme without sharing your calendar.</p>${button('Review Calendar Access','permission:Calendar','primary wide')}${go('Ask Something Else','home','text-button wide')}`);
 case 'action':return topbar('Review Action','conversation')+page(heading('Ready to create this event','Review the details before anything is saved.')+`<div class="summary"><p class="micro">Calendar event · Design sample</p><h4>Design Review</h4><p>Tomorrow, 3:00–3:30 PM</p><p>Asia/Kolkata · Personal calendar</p><p class="secondary">No attendees · No invitations will be sent</p></div><p class="source-note">Production shows the resolved date, destination calendar and current time zone. Calendar write access is checked before confirmation.</p><div class="stack">${button('Create Event · Preview','confirm-event','primary wide')}${go('Edit Request','conversation','secondary-button wide')}${go('Cancel','conversation','text-button wide')}</div>`);
 case 'success':return topbar('Confirmation','conversation')+page(`${presence('success')}<h3 class="heading">Event preview complete</h3><p class="secondary">No calendar was changed. In the app, success appears only after the write is verified.</p>${go('Done','home','primary wide')}`,'center');
 case 'history':{const items=state.history.filter(x=>x.title.toLowerCase().includes(state.historyQuery.toLowerCase()));return topbar('History')+page(heading('A place to pick things up')+`<input type="search" id="history-search" aria-label="Search conversations" placeholder="Search conversations" value="${escapeHTML(state.historyQuery)}"><div id="history-results">${historyContent(items)}</div>`);}
 case 'services':return topbar('Connected Services')+page(heading('Connect what matters','Give Suzzme more context only when you choose.')+`<h4 class="section-heading">On your device</h4><div class="list">${row('calendar','Calendar','Your schedule · Permission required.','Manage','permission:Calendar')}${row('person','Contacts','People you ask about · Permission required.','Manage','permission:Contacts')}${row('file','Selected Files','Only the documents you choose.','Choose','go:attachment')}</div><h4 class="section-heading">Connected accounts · Network</h4><div class="list">${row('mail','Gmail',state.connected?'Demo connection · Message metadata only.':'Not connected · Uses Google services.','Manage','go:service-detail')}</div><p class="source-note">${state.connected?'Sample account state only.':'No connected services.'} Connected accounts use the network even when an answer is generated on your device.</p>`);
 case 'service-detail':return topbar('Gmail','services')+page(heading('Gmail',state.connected?'Design sample · Connected account':'Connect only if useful.')+`<div class="summary"><p>Scope: message metadata</p><p class="secondary">Google account access uses a network. Production must show the exact authorized scope, account, last update and health.</p></div><div class="stack">${button(state.connected?'Disconnect Demo Account':'Preview Connected State','connection','primary wide')}${go('Back to Services','services','text-button wide')}</div><p class="small-note">This does not sign in, authorize Google or fetch mail. OAuth success and errors must come from the actual controller.</p>`);
 case 'settings':return topbar('Settings')+page(heading('Make Suzzme yours')+`<h4 class="section-heading">Suzzme</h4><div class="list">${row('settings','General','Behavior and language','','go:general')}${row('speaker','Voice','Speech, input and playback','','go:voice-settings')}${row('device','Appearance','System, light and dark','','go:appearance')}</div><h4 class="section-heading">Intelligence & Context</h4><div class="list">${row('text','Intelligence','Responses and supported capabilities','','go:intelligence-settings')}${row('shield','Personal Context','Allowed sources and saved preferences','','go:memory')}${row('link','Connected Services','Authorized network accounts','','go:services')}</div><h4 class="section-heading">Your Control</h4><div class="list">${row('bell','Notifications','Proactive assistance','','go:notifications')}${row('shield','Privacy & Permissions','Access and data controls','','go:privacy')}${row('device','Devices','Capabilities and sync availability','','go:devices')}${row('text','About','Version, privacy and help','','go:about')}</div>`);
 case 'appearance':return topbar('Appearance','settings')+page(heading('Feels like your device','Choose an appearance. Presence stays recognizable in both modes.')+`<label class="toggle">Appearance<select id="app-appearance">${['system','light','dark'].map(x=>`<option ${state.appearance===x?'selected':''} value="${x}">${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></label>${presence('Thinking')}<p class="status">Thinking it through…</p><h4 class="section-heading">Accessibility previews</h4>${toggle('Increase Contrast','contrast')}${toggle('Reduce Transparency','transparency')}<p class="source-note">The native app follows system accessibility preferences. Presence themes change only intelligence surfaces.</p>`);
 case 'voice-settings':return topbar('Voice','settings')+page(heading('Talk your way','Voice availability follows your device and language.')+`<div class="list">${row('mic','Microphone','Requested when you start talking.',state.permissionStatus.Microphone||'Not Asked','permission:Microphone')}${row('text','Speech Recognition','Availability may depend on language and network.',state.permissionStatus['Speech Recognition']||'Not Asked','permission:Speech Recognition')}</div><label class="toggle">Spoken Responses<select id="speech-choice"><option>When Voice Is Active</option><option>Off</option></select></label>${button('Preview Voice','read','secondary-button wide')}<p class="source-note">Audio level represents listening input only. Speaking motion must not pretend to be a real waveform.</p>`);
 case 'general':return topbar('General','settings')+page(heading('Simple by default')+`<div class="list">${row('text','Language','Follow the device language.','System')}${row('history','Recent Conversations','Local history controls.','Manage','go:history')}${row('settings','Mac Shortcut','Choose an available combination.','Mac only')}</div><p class="source-note">Suggested Mac invocation: Control–Option–Space, after checking conflicts. Never take over Spotlight.</p>`);
 case 'intelligence-settings':return topbar('Intelligence','settings')+page(heading('Helpful, within reach')+`<label class="toggle">Response Length<select id="length-choice"><option>Balanced</option><option>Brief</option><option>Detailed</option></select></label><div class="list">${row('device','On-Device Intelligence','Availability is checked at runtime.','Device dependent')}${row('context','Contextual Assistance','Only selected context.','Manage','go:context')}</div><p class="source-note">Model unavailable? Keep local browsing and supported actions available. Never silently switch private context to a cloud provider.</p>`);
 case 'notifications':return topbar('Notifications','settings')+page(heading('Useful, never noisy','Choose when Suzzme can bring something to your attention.')+toggle('Proactive Assistance','proactive')+toggle('Show Personal Details in Previews','preview')+`<div class="list">${row('bell','Notification Permission','System permission is separate from these preferences.',state.permissionStatus.Notifications||'Not Asked','permission:Notifications')}</div><div class="summary"><p class="micro">Example · Details hidden</p><h4>An update is ready</h4><p class="secondary">Open Suzzme to view it.</p>${go('Why Am I Seeing This?','why','text-button')}</div><p class="source-note">Opt in by category. Respect Focus and system delivery settings. Avoid repeats for the same item.</p>`);
 case 'why':return topbar('Why This Update?','notifications')+page(heading('You’re in control','This is a notification design example.')+`<p class="secondary">In production, show the reminder category, authorized source and trigger that caused this update.</p>${go('Manage Proactive Assistance','notifications','primary wide')}`);
 case 'devices':return topbar('Devices','settings')+page(heading('Built for your devices','Features follow the capabilities available here.')+`<div class="summary"><div class="panel-heading">${icon('device')}<h4>This Device</h4></div><p class="secondary">Production reads platform and runtime capability status. This prototype makes no hardware claim.</p></div><div class="list">${row('text','On-Device Model','Available / unavailable / preparing.','Runtime')}${row('mic','Speech','Language and permission dependent.','Runtime')}${row('context','Screen Context','Explicit snapshots on Mac.','Mac only')}${row('device','Live Activities','System authorization and supported hardware.','Optional')}</div><h4 class="section-heading">Sync</h4><p class="secondary">Device sync is not enabled in this design release. Show a switch only when implemented, with clear data scope and explicit opt in.</p>`);
 case 'about':return topbar('About','settings')+page(`${presence('idle','small-presence')}<h3 class="heading">Suzzme</h3><p class="secondary">Present when needed. Invisible when not.</p><div class="list">${row('shield','Privacy','What Suzzme uses and how to stop.','','go:privacy')}${row('text','Design Specification','Source, platform requirements and acceptance.','','open-spec')}${row('text','Acknowledgements','System typography and symbols.','Design preview')}</div><p class="small-note">Design edition 01 · 7 October 2026. Production displays the app’s actual version.</p>`);
 case 'permissions':return topbar('Permissions','privacy')+page(heading('You choose the access','Review the purpose before deciding. Nothing is granted by this prototype.')+`<div class="list">${permissions.map(([n,i,d,note])=>row(i,n,d+' '+note,state.permissionStatus[n]||'Not Asked',`permission:${n}`)).join('')}</div>${go('Connected Accounts','services','text-button wide')}`);
 case 'permission-explainer':{const p=permissions.find(x=>x[0]===state.permission)||permissions[0];return topbar(p[0],'permissions')+page(heading(`Use ${p[0].toLowerCase()}?`,p[2])+`<p class="secondary">${p[3]}. You can continue without this access.</p><p class="micro">Current design state: ${state.permissionStatus[p[0]]||'Not Asked'}</p><div class="stack">${button(state.permissionStatus[p[0]]==='Denied'?'Preview System Settings Recovery':'Continue to Permission Preview','system-preview','primary wide')}${go('Not Now','permissions','secondary-button wide')}</div><p class="source-note">The native app opens Apple’s permission dialog or the relevant picker. Denied access leads to Settings, never a repeated prompt.</p>`);}
 case 'system-permission':return topbar('Permission Simulation','permission-explainer')+page(heading('Choose a design outcome','These are prototype controls, not an Apple permission dialog.')+`<div class="stack">${button('Simulate Allowed','permission-result:Allowed','primary wide')}${button('Simulate Denied','permission-result:Denied','secondary-button wide')}${button('Simulate Restricted','permission-result:Restricted','secondary-button wide')}${go('Cancel','permissions','text-button wide')}</div><p class="source-note">Production requests just the access needed. Restricted and unsupported states provide useful explanations and another way forward.</p>`);
 case 'privacy':return topbar('Privacy','settings')+page(heading('Private by choice','Know what Suzzme is using, why, and how to stop.')+`<div class="list">${row('shield','Permissions','Review device access.','','go:permissions')}${row('context','Current Context',state.shared?'Selected text · This session.':'Nothing is being shared.','','go:context')}${row('person','Saved Preferences','Understand and remove what is remembered.','','go:memory')}${row('history','Conversation History','Local history and deletion.','','go:history')}${row('link','Connected Accounts','Network use and authorized scopes.','','go:services')}</div><p class="source-note">On-device describes a particular processing route, not every feature. Account access, some speech features and optional services may require a network.</p>${button('Delete Demo History','clear-history','secondary-button wide danger')}`);
 case 'memory':return topbar('Personal Context','settings')+page(heading('What Suzzme can use','Source and purpose are always visible.')+`<div class="list">${row('calendar','Calendar','Schedule questions only after permission.','Manage','permission:Calendar')}${row('person','Contacts','People you ask about.','Manage','permission:Contacts')}${row('file','Selected Context',state.shared?'A sample passage in this session.':'Nothing is being shared.','Manage','go:context')}</div><h4 class="section-heading">Saved Preferences</h4>${toggle('Remember Approved Preferences','remember')}<p class="secondary">No preferences saved yet. In production, each saved item shows its source, date and Delete action.</p>`);
 case 'menu':return page(`<div class="menu-bar"><span>Finder · File · Edit · View</span>${presence('idle','tiny')}</div><div class="notch-panel"><div class="panel-heading">${presence('idle','tiny')}<h4>Suzzme</h4><span class="caption" style="margin-left:auto">Ready</span></div><p class="secondary">A little help, right here.</p>${button(icon('mic')+' Talk to Suzzme','voice-start','primary wide')}<h4 class="section-heading">Recent</h4><p class="caption">${state.history.length?escapeHTML(state.history[0].title):'No recent interactions.'}</p><div class="list">${row('text','Summarize Something','Choose what you share.','','go:attachment')}${row('text','Open Suzzme','Continue in a full window.','','go:mac-window')}${row('settings','Settings','⌘,','','go:settings')}</div></div>`)+composer();
 case 'notch':return page(`<div class="notch-anchor" aria-label="Hardware anchor illustration"></div><p class="micro" style="text-align:center">App-owned panel below the hardware</p><div class="notch-panel"><div class="panel-heading">${presence('Thinking','tiny')}<h4>Suzzme</h4><span class="caption" style="margin-left:auto">Thinking…</span></div><p class="secondary">Preparing your response.</p><div class="buttons">${go('Open Answer','conversation','primary')}${button('Dismiss','dismiss-panel','secondary-button')}</div></div><div style="height:70px"></div><h4 class="section-heading">Without a notch</h4><p class="secondary">The same compact companion opens from the menu bar or as a floating panel.</p>${go('Preview the Floating Panel','floating','secondary-button wide')}<p class="source-note">No physical-notch modification. Fit the safe screen region; relocate when geometry or display changes. Private content stays hidden in passive states.</p>`);
 case 'floating':return page(`<div class="notch-panel"><div class="panel-heading">${presence('idle','tiny')}<h4>Suzzme</h4>${button(icon('close'),'dismiss-panel','','aria-label="Dismiss assistant panel"')}</div><p class="secondary">What would you like a hand with?</p>${state.shared?`<div class="chips">${chip('Selected text · This session')}${button('Stop Sharing','stop-context','chip')}</div>`:'<p class="caption">Nothing is being shared.</p>'}<div class="summary"><p class="micro">Compact answer · Sample</p><p>Start with the decision you need from your review.</p></div>${go('Continue in Full Window','conversation','text-button wide')}</div><p class="source-note">Suggested shortcut: ⌃⌥Space, configurable after a conflict check. Escape closes a passive panel; active work offers Stop first.</p>`)+composer();
 case 'errors':return topbar('States')+page(heading('Clarity when plans change')+`<label class="toggle">Preview State<select id="error-choice">${Object.keys(errorData).map(k=>`<option value="${k}" ${state.error===k?'selected':''}>${errorData[k][0]}</option>`).join('')}</select></label>`+errorPanel());
 case 'share':return topbar('Share','conversation')+page(heading('Share this response','In production, use the native share sheet. This sample only copies the answer.')+`${button('Copy Sample Response','copy','primary wide')}${go('Cancel','conversation','text-button wide')}`);
 case 'flows':return topbar('Prototype Flows')+page(heading('Eight useful journeys','Choose a path. Review controls stay outside the product.')+`<div class="flow-grid">${Object.entries(flows).map(([id,f])=>button(`<strong>${id} · ${f.name}</strong><span>${f.routes.map(r=>routeLabel(r)).join(' → ')}</span>`,`flow:${id}`,'flow-card')).join('')}</div>`);
 default:return home();
 }
}
function historyContent(items){if(!state.history.length)return `<div style="text-align:center;padding:36px 0">${icon('history')}<h4 style="margin-top:18px">No conversations yet.</h4><p class="secondary">Your recent conversations will appear here when you choose to keep history.</p>${go('Ask Suzzme','home','primary')}${state.deleted?button('Undo Delete','undo-delete','secondary-button'):''}</div>`;if(!items.length)return '<p class="secondary">No conversations match your search. Try another phrase.</p>';return `<p class="micro">Today · Design session</p><div class="list">${items.map(x=>row('text',escapeHTML(x.title),'Sample conversation · Stored in this page only.','Open',`history-open:${x.id}`)+button('Delete Conversation',`delete:${x.id}`,'text-button danger')).join('')}</div>${state.deleted?button('Undo Delete','undo-delete','secondary-button'):''}`;}
const errorData={offline:['You’re offline','Connected accounts can’t update right now. Your draft is safe.','Use Local Features','home'],unsupported:['Not available on this device','You can still type, browse saved information and use supported actions.','See Device Capabilities','devices'],denied:['Microphone access is off','Allow it in Settings when you want to speak, or continue by typing.','Type Instead','home'],model:['On-device intelligence isn’t ready','Check device requirements and model availability. We won’t send your context to another service automatically.','See Capabilities','devices'],speech:['Speech recognition is unavailable','Try typing while this language or recognition service is unavailable.','Return to Text','home'],connection:['Gmail couldn’t connect','Your account wasn’t authorized. Check your connection and try again.','Review Connection','service-detail'],context:['Context is unavailable','The shared item is no longer available. Choose it again.','Choose Context','attachment'],action:['The event wasn’t saved','Your calendar may have changed. Review the details and current access before trying again.','Review Action','action'],empty:['No connected services','Connect services when you want Suzzme to help with more of your day.','View Services','services'],loading:['Checking your context…','You can cancel and keep your draft. No private details appear in progress text.','Cancel','home']};
function errorPanel(){const [title,copy,label,route]=errorData[state.error];return `<div style="padding:30px 0">${state.error==='loading'?presence('Working'):icon(state.error==='empty'?'link':'warning')}<h4 style="margin-top:20px">${title}</h4><p class="secondary">${copy}</p>${go(label,route,'primary wide')}${state.error==='denied'?button('Review Microphone Access','permission:Microphone','text-button wide'):''}</div>`;}
const flows={A:{name:'First Launch',routes:['splash','welcome','privacy-intro','voice-intro','permissions','ready','home']},B:{name:'Quick Question',routes:['home','thinking','conversation','conversation']},C:{name:'Voice',routes:['voice','voice','voice','voice','home'],voice:['Listening','Understanding','Thinking','Speaking','Idle']},D:{name:'Context Assistance',routes:['floating','attachment','context','thinking','conversation','context']},E:{name:'Action',routes:['conversation','thinking','action','success']},F:{name:'Dynamic Island',routes:['home','island','island','island','conversation','home']},G:{name:'Mac Notch',routes:['notch','floating','thinking','notch','conversation']},H:{name:'Permissions',routes:['permission-explainer','system-permission','permissions','home']}};
function routeLabel(r){return {'splash':'Splash',welcome:'Meet Suzzme','privacy-intro':'Privacy','voice-intro':'Voice',permissions:'Permissions',ready:'Ready',home:'Home',thinking:'Thinking',conversation:'Response',voice:'Voice',floating:'Invoke',attachment:'Choose context',context:'Context',action:'Review action',success:'Verified outcome',island:'Live Activity',notch:'Notch panel','permission-explainer':'Explain','system-permission':'System outcome'}[r]||r;}
function renderFlow(){const node=$('#flow-controls');if(!state.flow){node.innerHTML=go('Explore Prototype Flows','flows');return;}const f=flows[state.flow];node.innerHTML=`<span>${state.flow} · ${f.name} · ${state.step+1}/${f.routes.length}</span>${button('Back','flow-back','',state.step===0?'disabled':'')}${button(state.step===f.routes.length-1?'Finish':'Next','flow-next')}${button('Exit Flow','flow-exit')}`;}
function setFlowStep(){const f=flows[state.flow];state.route=f.routes[state.step];if(state.flow==='C')state.voice=f.voice[state.step];if(state.flow==='D')state.shared=state.step>=2&&state.step<5;if(state.flow==='H')state.permission='Microphone';navigate(state.route);}
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function handle(action){if(action.startsWith('go:')){const r=action.slice(3);if(['menu','notch','floating','mac-window'].includes(r))state.viewport='mac';if(r==='light'||r==='dark')state.appearance=r;navigate(r);return;}if(action.startsWith('permission:')){state.permission=action.slice(11);navigate('permission-explainer');return;}if(action.startsWith('permission-result:')){state.permissionStatus[state.permission]=action.slice(18);navigate('permissions');toast(`Design state: ${state.permission} ${state.permissionStatus[state.permission].toLowerCase()}. No system permission changed.`);return;}if(action.startsWith('flow:')){state.flow=action.slice(5);state.step=0;if(['G','D'].includes(state.flow))state.viewport='mac';else state.viewport='phone';setFlowStep();return;}if(action.startsWith('history-open:')){const x=state.history.find(x=>x.id===Number(action.slice(13)));if(x)state.question=x.title;navigate('conversation');return;}if(action.startsWith('delete:')){state.deleted=state.history.find(x=>x.id===Number(action.slice(7)));state.history=state.history.filter(x=>x!==state.deleted);render();toast('Conversation deleted from the preview. Undo is available.');return;}
 switch(action){case 'ask':{const input=$('#question');state.question=input?.value.trim()||'Help me prepare for my design review.';state.history.unshift({id:Date.now(),title:state.question});navigate('thinking');toast('Authored sample response; no AI service is called. Use Continue to view it.');$('#screen .page').insertAdjacentHTML('beforeend',go('Continue to Sample Response','conversation','primary'));break;}
 case 'voice-start':state.permission='Microphone';if(state.permissionStatus.Microphone!=='Allowed')navigate('permission-explainer');else{state.voice='Listening';navigate('voice');}break;
 case 'system-preview':navigate('system-permission');break;
 case 'voice-next':state.voice=['Listening','Understanding','Thinking','Speaking'][(['Listening','Understanding','Thinking','Speaking'].indexOf(state.voice)+1)%4];render();break;
 case 'voice-stop':state.voice='Understanding';render();toast('Demo recording stopped.');break;
 case 'voice-end':state.voice='Idle';navigate('home');break;
 case 'cancel-work':navigate('home');toast('Preview canceled.');break;
 case 'use-context':state.shared=true;navigate('context');break;
 case 'stop-context':state.shared=false;render();toast('Selected sample removed from active context.');break;
 case 'context-ask':state.question='Explain the selected passage.';navigate('conversation');break;
 case 'screen-preview':if(!state.viewport.startsWith('mac'))toast('Current-screen snapshots are available on Mac only. Use selected text on iPhone.');else{state.permission='Screen Sharing';navigate('permission-explainer');}break;
 case 'confirm-event':state.confirmed=true;if(state.flow==='E'&&state.step===2)state.step=3;navigate('success');break;
 case 'connection':state.connected=!state.connected;render();toast(state.connected?'Connected state preview. No Google account was authorized.':'Demo account disconnected.');break;
 case 'clear-history':if(state.history.length){state.deleted=[...state.history];state.history=[];render();toast('Demo history deleted.');$('#screen .page').insertAdjacentHTML('beforeend',button('Undo Delete','undo-delete','secondary-button wide'));}else toast('No demo history to delete.');break;
 case 'undo-delete':if(state.deleted){state.history.unshift(...(Array.isArray(state.deleted)?state.deleted:[state.deleted]));state.deleted=null;}render();break;
 case 'shorten':$('#screen .response').innerHTML=`<div class="byline">${presence('idle','tiny')}Suzzme</div><p>Lead with the problem, name the tradeoff, then agree on one next step.</p><p class="micro">Authored short variant · No model call</p>`;toast('Short response variant.');break;
 case 'copy':navigator.clipboard?.writeText('Lead with the problem, name the tradeoff, then agree on one next step.').then(()=>toast('Sample response copied.')).catch(()=>toast('Clipboard unavailable. Select the response text to copy.'));break;
 case 'read':state.voice='Speaking';navigate('voice');toast('Speaking design preview. No audio playback.');break;
 case 'dismiss-panel':navigate('home');toast('Panel dismissed in this preview.');break;
 case 'open-spec':window.open('SPECIFICATION.md','_blank','noopener');break;
 case 'flow-back':state.step=Math.max(0,state.step-1);setFlowStep();break;
 case 'flow-next':if(state.flow==='E'&&state.step===2){toast('Use Create Event · Preview to acknowledge the action before continuing.');break;}if(state.step===flows[state.flow].routes.length-1){state.flow=null;navigate('flows');}else{state.step++;setFlowStep();}break;
 case 'flow-exit':state.flow=null;navigate('flows');break;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)handle(b.dataset.action);});
document.addEventListener('change',e=>{if(e.target.id==='appearance'||e.target.id==='app-appearance'){state.appearance=e.target.value;render();}else if(e.target.id==='viewport'){state.viewport=e.target.value;render();}else if(e.target.dataset.toggle){state.toggles[e.target.dataset.toggle]=e.target.checked;if(['contrast','transparency'].includes(e.target.dataset.toggle))render();}else if(e.target.id==='error-choice'){state.error=e.target.value;render();}else if(['speech-choice','length-choice'].includes(e.target.id))toast('Preference preview updated.');});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search')renderCatalog(e.target.value);if(e.target.id==='history-search'){state.historyQuery=e.target.value;$('#history-results').innerHTML=historyContent(state.history.filter(x=>x.title.toLowerCase().includes(state.historyQuery.toLowerCase())));}});
$('#motion').addEventListener('click',()=>{state.motion=!state.motion;$('#motion').setAttribute('aria-pressed',String(state.motion));render();});$('#large-text').addEventListener('click',()=>{state.largeText=!state.largeText;$('#large-text').setAttribute('aria-pressed',String(state.largeText));render();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='question'){e.preventDefault();handle('ask');}if(e.key==='Escape'){if(state.route==='voice'){handle('voice-end');}else if(state.route==='thinking'){handle('cancel-work');}else{navigate('home');}}if(e.metaKey&&e.key===','){e.preventDefault();navigate('settings');}if(e.metaKey&&e.key==='f'&&state.route==='history'){e.preventDefault();$('#history-search')?.focus();}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(r&&r!==state.route){state.route=r;render();}});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.appearance==='system')render();});
if(location.hash)state.route=location.hash.slice(1);render();
